app.Use(async (context, next) =>            // each middleware links the next
{
    if (!context.Request.Headers.ContainsKey("X-Api-Key"))
    {
        context.Response.StatusCode = 401;
        return;                             // short-circuit: chain stops
    }
    await next.Invoke(context);             // forward
});
app.Run(async context => await context.Response.WriteAsync("ok"));  // terminal

public abstract class Handler
{
    public Handler? Successor { get; set; }

    public virtual bool Handle(Request r) => Successor?.Handle(r) ?? false;
}

